/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MAM0_ACR_MAX_COUNT        91U
#define MAM1_ACR_MAX_COUNT        63U
#define MAM2_ACR_MAX_COUNT        280U

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* MAM Device Private Data */

struct fc7300_mam_config_s
{
  uint32_t reg_base;                /* MAM register base address */
  uint32_t irq;                     /* Interrupt ID */
  uint32_t irq_priority;            /* Interrupt priority */
  uint32_t instance_no;             /* MAM instance number */
  uint32_t BSTCR;                   /* Burst Control */
  uint32_t WDGCR;                   /* Watchdog Control */
  uint32_t TOCR;                    /* Timeout Control */
  uint32_t ACR[MAM2_ACR_MAX_COUNT]; /* Access Control */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static inline uint32_t
fc7300_mam_getreg(struct fc7300_mam_config_s *priv, uint16_t offset);
static inline void fc7300_mam_putreg(struct fc7300_mam_config_s *priv,
                                     uint16_t offset, uint32_t value);
static int fc7300_mam_isr(int irq, void *context, void *arg);

