/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fc7300_mam_getreg
 *
 * Description:
 *   Get a 32-bit register value by offset
 *
 * Input Parameters:
 *   priv   - MAM device private data
 *   offset - Register offset with respect to the base address of the MAM
 *            peripheral
 *
 * Returned Value:
 *   The 32-bit value retrieved from the register
 *
 ****************************************************************************/

static inline uint32_t
fc7300_mam_getreg(struct fc7300_mam_config_s *priv, uint16_t offset)
{
  return getreg32(priv->reg_base + offset);
}

/****************************************************************************
 * Name: fc7300_mam_putreg
 *
 * Description:
 *  Put a 32-bit register value by offset
 *
 * Input Parameters:
 *   priv   - MAM device private data
 *   offset - Register offset with respect to the base address of the MAM
 *            peripheral
 *   value  - The 32-bit value that should be put into the register
 *
 ****************************************************************************/

static inline void fc7300_mam_putreg(struct fc7300_mam_config_s *priv,
                                     uint16_t offset, uint32_t value)
{
  putreg32(value, priv->reg_base + offset);
}

/****************************************************************************
 * Name: fc7300_mam_isr
 *
 * Description:
 *   Common MAM interrupt service routine
 *
 ****************************************************************************/

static int fc7300_mam_isr(int irq, void *context, void *arg)
{
  struct fc7300_mam_config_s *priv = (struct fc7300_mam_config_s *)arg;

  DEBUGASSERT(priv != NULL);

  uint32_t i;
  int ret;
  uint32_t reg_value;

  reg_value = fc7300_mam_getreg(priv, FC7300_MAM_WDGCR_OFFSET);

  for (i = 0U; i < 7U; ++i)
    {
      if (reg_value & (0x00010000U << i))
        {
          ret = fc7300_mam_user_callback(priv->instance_no, i);
          if (ret == 0U)
            {
              fc7300_mam_putreg(priv, FC7300_MAM_WDGCR_OFFSET,
                                priv->WDGCR | (0x00010000U << i));
            }
        }
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fc7300_mam_init
 *
 * Description:
 *   Hardware level initializes the mam Driver settings based on the
 * configuration.
 *
 ****************************************************************************/

void fc7300_mam_init(void)
{
  uint32_t i;

  /* MAM0 Init */

  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam0_config,
                    FC7300_MAM_BSTCR_OFFSET,
                    g_mam0_config.BSTCR);
  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam0_config,
                    FC7300_MAM_WDGCR_OFFSET,
                    g_mam0_config.WDGCR);
  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam0_config,
                    FC7300_MAM_TOCR_OFFSET,
                    g_mam0_config.TOCR);
  for (i = 0U; i < MAM0_ACR_MAX_COUNT; ++i)
    {
      fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam0_config,
                        FC7300_MAM_ACR_REG_OFFSET(i),
                        g_mam0_config.ACR[i]);
    }

  /* MAM1 Init */

  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam1_config,
                    FC7300_MAM_BSTCR_OFFSET,
                    g_mam1_config.BSTCR);
  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam1_config,
                    FC7300_MAM_WDGCR_OFFSET,
                    g_mam1_config.WDGCR);
  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam1_config,
                    FC7300_MAM_TOCR_OFFSET,
                    g_mam1_config.TOCR);
  for (i = 0U; i < MAM1_ACR_MAX_COUNT; ++i)
    {
      fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam1_config,
                        FC7300_MAM_ACR_REG_OFFSET(i),
                        g_mam1_config.ACR[i]);
    }

  /* MAM2 Init */

  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam2_config,
                    FC7300_MAM_BSTCR_OFFSET,
                    g_mam2_config.BSTCR);
  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam2_config,
                    FC7300_MAM_WDGCR_OFFSET,
                    g_mam2_config.WDGCR);
  fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam2_config,
                    FC7300_MAM_TOCR_OFFSET,
                    g_mam2_config.TOCR);
  for (i = 0U; i < MAM2_ACR_MAX_COUNT; ++i)
    {
      fc7300_mam_putreg((struct fc7300_mam_config_s *)&g_mam2_config,
                        FC7300_MAM_ACR_REG_OFFSET(i),
                        g_mam2_config.ACR[i]);
    }
}

/****************************************************************************
 * Name: fc7300_mam_irq_attach
 *
 * Description:
 *   Interrupt registration function after the system starts.
 *
 ****************************************************************************/

void fc7300_mam_irq_attach(void)
{
  irq_attach(g_mam0_config.irq, fc7300_mam_isr,
            (struct fc7300_mam_config_s *)&g_mam0_config);
#  ifdef CONFIG_ARCH_IRQPRIO
  up_prioritize_irq(g_mam0_config.irq, g_mam0_config.irq_priority);
#  endif
  up_enable_irq(g_mam0_config.irq);

  irq_attach(g_mam1_config.irq, fc7300_mam_isr,
            (struct fc7300_mam_config_s *)&g_mam1_config);
#  ifdef CONFIG_ARCH_IRQPRIO
  up_prioritize_irq(g_mam1_config.irq, g_mam1_config.irq_priority);
#  endif
  up_enable_irq(g_mam1_config.irq);

  irq_attach(g_mam2_config.irq, fc7300_mam_isr,
            (struct fc7300_mam_config_s *)&g_mam2_config);
#  ifdef CONFIG_ARCH_IRQPRIO
  up_prioritize_irq(g_mam2_config.irq, g_mam2_config.irq_priority);
#  endif
  up_enable_irq(g_mam2_config.irq);
}

/****************************************************************************
 * Name: fc7300_mam_injection_open
 *
 * Description:
 *   Open mam injection.
 *
 ****************************************************************************/

void fc7300_mam_injection_open(uint32_t mam_idx, uint32_t acr_idx, uint32_t block_idx)
{
  struct fc7300_mam_config_s *p_config = NULL;

  switch (mam_idx)
    {
      case 0U:
        p_config = (struct fc7300_mam_config_s *)&g_mam0_config;
        break;
      case 1U:
        p_config = (struct fc7300_mam_config_s *)&g_mam1_config;
        break;
      case 2U:
        p_config = (struct fc7300_mam_config_s *)&g_mam2_config;
        break;
      default:
        break;
    }

  if (p_config != NULL)
    {
      fc7300_mam_putreg(p_config,
        FC7300_MAM_ACR_REG_OFFSET(acr_idx), (0xFUL << (block_idx * 4)));
    }
}

/****************************************************************************
 * Name: fc7300_mam_injection_close
 *
 * Description:
 *   Close mam injection.
 *
 ****************************************************************************/

void fc7300_mam_injection_close(uint32_t mam_idx, uint32_t acr_idx, uint32_t block_idx)
{
  struct fc7300_mam_config_s *p_config = NULL;

  switch (mam_idx)
    {
      case 0U:
        p_config = (struct fc7300_mam_config_s *)&g_mam0_config;
        break;
      case 1U:
        p_config = (struct fc7300_mam_config_s *)&g_mam1_config;
        break;
      case 2U:
        p_config = (struct fc7300_mam_config_s *)&g_mam2_config;
        break;
      default:
        break;
    }

  if (p_config != NULL)
    {
      fc7300_mam_putreg(p_config,
        FC7300_MAM_ACR_REG_OFFSET(acr_idx), 0UL);
    }
}
